import {initial,chooseAction,apply,actions,VERSION} from './engine.js';
self.onmessage=e=>{const {id,type,state,options={}}=e.data;try{if(type==='move'){self.postMessage({id,...chooseAction(state,options)});return;}if(type==='benchmark'){const results=[];const start=Date.now();for(let game=0;game<(options.games||3);game++){let s=initial(),nodes=0,counts={};while(!s.winner&&s.ply<(options.maxPlies||120)){const b=chooseAction(s,{seed:game*1000+s.ply+1,depth:1});if(!b.action||!actions(s).some(a=>a.id===b.action.id))throw new Error('Bot produced illegal action');nodes+=b.nodes;counts[b.action.kind]=(counts[b.action.kind]||0)+1;s=apply(s,b.action);}results.push({game:game+1,winner:s.winner||'limit',reason:s.reason||'Turn limit',plies:s.ply,nodes,counts});self.postMessage({id,progress:results.length,total:options.games||3,result:results.at(-1)});}self.postMessage({id,done:true,version:VERSION,results,ms:Date.now()-start});}}catch(err){self.postMessage({id,error:err.message});}};
